return [=[
body{font-family:sans-serif;font-size:16px;background:#d6d6d6;margin:0}#editor .editor_top{background:#f5f5f5;padding:20px;border-bottom:1px solid #b1afaf;box-shadow:0 -2px 4px 4px #00000026}#editor .cm-editor{font-size:14px}#editor .log{padding:0 20px}#editor .footer{text-align:center;margin:10px;font-size:12px;color:#838383}#editor .buttons_top{display:flex;align-items:center;gap:10px;margin-bottom:7px}#editor .buttons_top button,#editor .buttons_top select{font-size:16px;background:#8aa8cf;color:#294364;border:0;padding:5px 10px;border-radius:4px;transition:background .2s ease-in-out}:is(#editor .buttons_top button,#editor .buttons_top select):hover{background:#9cb5d6}#editor .buttons_top button:active{position:relative;top:1px}#editor .buttons_top select{margin-left:auto}#editor .status{background:#7bb87b;text-shadow:1px 1px 1px #488548;color:#fff;padding:4px 8px;white-space:pre-wrap;transition:background .2s ease-in-out}#editor .status.error{background:#c25353;text-shadow:1px 1px 1px #a73b3b}#editor .status.loading{background:#e9d674;text-shadow:1px 1px 1px #a9921b}#editor .result{border:1px solid silver;background:#fff;box-shadow:1px 1px 4px #00000026;color:#444;margin:10px 0}#editor .result.no_output{font-style:italic;color:#888;padding:10px}#editor .result .line{font-family:monospace}#editor .result .value{margin:5px;padding:5px;display:inline-block;vertical-align:top}#editor .result .value.string{color:#648164}#editor .result .value.string:before,#editor .result .value.string:after{font-weight:700;content:'"'}#editor .result .value.string.key:before{content:""}#editor .result .value.boolean{color:#664b66}#editor .result .value.number{color:#5076a0}#editor .result .value.function,#editor .result .value.recursion,#editor .result .value.metatable{color:#888;font-style:italic}#editor .result .value.recursion:before{content:"(recursion) ";font-style:normal;font-weight:700;font-size:14px}#editor .result .value.key{margin-right:0;padding-right:0}#editor .result .value.key:after{content:": ";font-style:normal;font-weight:700;color:#444}#editor .result .value:hover{background:#eee;border-radius:3px}#editor .result .value.expanded{border-left:1px dashed silver;margin-left:10px;padding:0}#editor .result .value.expanded:hover{background:#fff}#editor .result .tuple{margin-left:10px}#editor .result .tuple>.value{margin-top:0;margin-bottom:0}#editor .result .expandable{cursor:pointer;font-weight:700}#editor .result .closable{font-weight:700;vertical-align:top;display:inline-block;cursor:pointer;padding:5px;margin:5px}#editor .result .closable:first-child{margin-bottom:0}#editor .result .closable:last-child{margin-top:0}#editor .result .closable:hover{background:#eee;border-radius:3px}#editor .result .queries{font-family:monospace;background:#ddd;border:1px solid white}#editor .result .queries:before{content:"Queries:";display:block;background:#c4c4c4;border-bottom:1px solid #b4b4b4;text-shadow:1px 1px 0 #ddd;font-size:12px;padding:5px;font-family:sans-serif}#editor .result .queries .query{padding:5px}
]=]
